  const nw = 8, act=aS/nw, inh=iS/nw, harm=hS/nw;
  const bg1 = (Math.sin(fx*0.035+fy*0.022+t*0.7)+Math.sin(fx*0.028-fy*0.038+t*1.0))/2;
  const bg2 = Math.sin((fx+fy)*0.1+t*2.2)*0.25+Math.sin((fx-fy)*0.09-t*1.8)*0.25;
  const bg3 = Math.sin(fx*0.06*Math.cos(t*0.1)+fy*0.04*Math.sin(t*0.15)+t*1.3)*0.15;
