  const lap = (act-inh)*0.5;
  const rd2 = Math.tanh((rd1+lap*0.3+harm*0.2)*2.5);
  const cell = Math.tanh((Math.sin(fx*0.14)*Math.sin(fy*0.14)+Math.sin((fx+fy)*0.09+t)*0.45+Math.sin(fx*0.07-t*0.5)*Math.cos(fy*0.08+t*0.3)*0.3)*1.4)*0.25;
  const vein = Math.tanh(Math.sin(fx*0.06+Math.sin(fy*0.08+t*0.4)*3+t*0.5)*2)*0.15;
  const blend = rd2*0.6+cell*0.2+vein*0.1+harm*0.1;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,55],[12,42,88],[18,78,108],[24,125,128],
    [55,165,118],[130,190,85],[200,185,60],[220,150,55],
    [215,105,65],[185,65,75],[130,35,80],[75,18,62],[30,10,50],[5,12,55]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
